{
  "aktywnosci": [
    {
      "opis": "Dzieci siadają w kręgu na dywanie. Nauczyciel mówi szeptem 'słuchamy ciszy' i odkrywa mały budzik nakręcony na 30 sekund. Zadaniem dzieci jest wytrzymać w całkowitym bezruchu i ciszy, aż dzwonek zadzwoni. Potem rozmawiamy, co słyszały w ciszy (np. oddech, tykanie, kroki z korytarza). Zabawa uczy koncentracji i wrażliwości na dźwięki otoczenia.",
      "tytul": "Kto usłyszy ciszę? – słuchanie ciszy z budzikiem"
    },
    {
      "opis": "Nauczyciel przygotowuje na tackach cienką warstwę kaszy manny lub piasku. Każde dziecko dostaje patyczek i rysuje w kaszy ciche obrazki – np. ślimaka, chmury, serduszko. Potem delikatnie strzepuje i rysuje kolejny. Ćwiczy precyzję ruchów dłoni i uczy, że cicha, spokojna praca też jest przyjemna.",
      "tytul": "Ciche obrazki – rysowanie palcem w kaszy mannie"
    },
    {
      "opis": "Dzieci stają w kole i podają sobie z rąk do rąk mały dzwoneczek lub grzechotkę tak, aby nie wydać żadnego dźwięku. Kto spowoduje brzdęknięcie, siada i obserwuje. Potem zmieniamy przedmiot na piórko – trzeba je podać, nie upuszczając. Ćwiczy koordynację, kontrolę ruchów i wzajemną uwagę.",
      "tytul": "Cichy łańcuch – podawanie dzwoneczka bez dźwięku"
    }
  ]
}
